  'client-loans:read',
  'clients:read',
  'config-items:read',
  'connectors:read',
  'contracts:read',
  'credit-notes:read',
  'day-pack:read',
  'dedupe:read',
  'directory-groups:read',
  'dispatch-connector:read',
  'dispatch:read',
